    Snake *snake = createSnake(3, 5, 5, 32, 32);

    // Boucle de jeu
    bool running = true;
    while (running) {
        SDL_Event e;
        while (SDL_PollEvent(&e)) {
            if (e.type == SDL_QUIT) {
                running = false;
            } else if (e.type == SDL_KEYDOWN) {
                int dx, dy;
                switch (e.key.keysym.sym) {
                    case SDLK_LEFT:
                        dx = -1;
                        dy = 0;
                        break;
                    case SDLK_RIGHT:
                        dx = 1;
                        dy = 0;
                        break;
                    case SDLK_UP:
                        dx = 0;
                        dy = -1;
                        break;
                    case SDLK_DOWN:
                        dx = 0;
                        dy = 1;
                        break;
                    default:
                        break;
                }
                AnimationStep *steps = createAnimationSteps(snake, grid, dx, dy);
                if (steps != NULL) {
                    renderAnimation(renderer, steps, 10);
                }
                break;
            }
        }
    }

    // Libération de la mémoire
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
    free(grid->grid);
    free(grid);
    free(snake->segments);
    free(snake);
    return 0;
}
